#include "stdlib/lapack/base/dlasyf.h"
#include "validation.h"

/**
* Computes a partial symmetric factorization using Bunch-Kaufman pivoting.
*
* @param layout  storage layout
* @param uplo    selected matrix triangle
* @param N       matrix order
* @param NB      maximum factor panel width, at least two
* @param KB      scalar output number of factorized columns
* @param A       input/output matrix
* @param LDA     matrix leading dimension
* @param IPIV    signed one-based pivot output
* @param W       N-by-NB workspace
* @param LDW     workspace leading dimension
* @return        INFO or a negative argument position
*/
LAPACK_INT API_SUFFIX(c_dlasyf)( const LAPACK_LAYOUT layout, const LAPACK_UPLO uplo, const LAPACK_INT N, const LAPACK_INT NB, LAPACK_INT *KB, double *A, const LAPACK_INT LDA, LAPACK_INT *IPIV, double *W, const LAPACK_INT LDW ) {
	LAPACK_INT strideA1;
	LAPACK_INT strideA2;
	LAPACK_INT strideW1;
	LAPACK_INT strideW2;
	LAPACK_INT info;

	if ( layout != LAPACK_ROW_MAJOR && layout != LAPACK_COL_MAJOR ) return dlasyf_error( "c_dlasyf", -1 );
	if ( uplo != LAPACK_UPPER_TRIANGLE && uplo != LAPACK_LOWER_TRIANGLE ) return dlasyf_error( "c_dlasyf", -2 );
	if ( N < 0 ) return dlasyf_error( "c_dlasyf", -3 );
	if ( NB < 2 ) return dlasyf_error( "c_dlasyf", -4 );
	if ( LDA < 1 || LDA < N ) return dlasyf_error( "c_dlasyf", -7 );
	if ( LDW < 1 || ( layout == LAPACK_COL_MAJOR ? LDW < N : LDW < NB ) ) return dlasyf_error( "c_dlasyf", -10 );
	if ( layout == LAPACK_COL_MAJOR ) {
		strideA1 = 1;
		strideA2 = LDA;
		strideW1 = 1;
		strideW2 = LDW;
	} else {
		strideA1 = LDA;
		strideA2 = 1;
		strideW1 = LDW;
		strideW2 = 1;
	}
	info = dlasyf_validate( uplo, N, NB, KB, 0, A, strideA1, strideA2, 0, IPIV, 1, 0, W, strideW1, strideW2, 0 );
	if ( info != 0 ) {
		if ( info == -2 ) info = -3;
		else if ( info == -4 || info == -5 ) info = -5;
		else if ( info >= -9 && info <= -7 ) info = -7;
		else if ( info >= -12 && info <= -10 ) info = -8;
		else if ( info == -13 ) info = -9;
		else if ( info <= -14 ) info = -10;
		return dlasyf_error( "c_dlasyf", info );
	}
	return API_SUFFIX(c_dlasyf_ndarray)( uplo, N, NB, KB, 0, A, strideA1, strideA2, 0, IPIV, 1, 0, W, strideW1, strideW2, 0 );
}
